// Wellfound returns HTML — extract JSON-LD job postings
const html = $input.first().json.data || '';
const matches = [...html.matchAll(/<script type="application\/ld\+json">(.*?)<\/script>/gs)];
const jobs = [];
for (const m of matches) {
  try {
    const obj = JSON.parse(m[1]);
    if (obj['@type'] === 'JobPosting') {
      jobs.push({
        json: {
          external_id: obj.url || obj.identifier?.value || '',
          source: 'wellfound',
          title: obj.title || '',
          company: obj.hiringOrganization?.name || 'Unknown',
          location: obj.jobLocation?.address?.addressLocality || 'Remote',
          is_remote: (obj.jobLocationType || '').includes('TELECOMMUTE'),
          url: obj.url || '',
          description: obj.description || '',
          required_skills: [],
          posted_at: obj.datePosted || null,
          currency: obj.baseSalary?.currency || 'USD',
          salary_min: obj.baseSalary?.value?.minValue || null,
          salary_max: obj.baseSalary?.value?.maxValue || null
        }
      });
    }
  } catch(e) {}
}
return jobs.length ? jobs : [{ json: { _empty: true } }];

const jobs = $input.all().map(i => i.json);
if (jobs.length === 0) return [];
return [{ json: { source: 'wellfound', jobs } }];
